// ---------- geometry helpers ----------

const r1 = (n: number) => Math.round(n * 10) / 10

/** A ruffled circle: n scallops bulging `depth` past radius r, centred on (cx, cy). */
const scallop = (r: number, n: number, depth: number, cx = 0, cy = 0, spin = 0) => {
  const pt = (a: number, rr: number) => `${r1(cx + rr * Math.cos(a))} ${r1(cy + rr * Math.sin(a))}`
  const step = (Math.PI * 2) / n
  let d = `M${pt(spin, r)}`
  for (let i = 0; i < n; i++) {
    const a = spin + i * step
    d += `Q${pt(a + step / 2, r + depth * 2)} ${pt(a + step, r)}`
  }
  return d + 'Z'
}

// ---------- message shapes: ruffled cabbage leaves ----------
// 96-unit drawing cut nine ways at 32: corners draw once, each edge tile holds two ruffles and repeats.

const LEAF_EDGE =
  'M32 6Q40 1 48 6Q56 1 64 6' +
  'Q76.2 2.4 82.4 13.6Q93.6 19.8 90 32' +
  'Q95 40 90 48Q95 56 90 64' +
  'Q93.6 76.2 82.4 82.4Q76.2 93.6 64 90' +
  'Q56 95 48 90Q40 95 32 90' +
  'Q19.8 93.6 13.6 82.4Q2.4 76.2 6 64' +
  'Q1 56 6 48Q1 40 6 32' +
  'Q2.4 19.8 13.6 13.6Q19.8 2.4 32 6Z'

// leaf veins fanning from the corners
const VEINS_TL = 'M8 30Q16 16 30 8M12 22L6 18M18 14L14 8M22 11L25 6'
const VEINS_BR = 'M88 66Q80 80 66 88M84 74L90 78M78 82L82 88M74 85L70 92'

// a tiny version of the logo — cabbage sitting on the sideways K — in the bottom-right corner of each reply
const STAMP_HEAD = scallop(4.6, 9, 0.8, 75, 70.6)
const STAMP_K = 'M67.5 76.5H82.5M75 76.5L70.5 81.5M75 76.5L79.5 81.5'
const STAMP_FOLDS = 'M75 75Q73.5 72 75 69M72 74Q71 71.5 72.5 68.5M78 74Q79 71.5 77.5 68.5'

const riso = (color: `#${string}`) => ({ x: 5, y: 5, blur: 0, color })

const userLeaf = (bg: ThemeMessageRule['backgroundColor'], text: ThemeMessageRule['color'], vein: `#${string}`, shadow: `#${string}`, rotate: number): ThemeMessageRule => ({
  backgroundColor: bg,
  color: text,
  paddingX: 18,
  paddingY: 14,
  shadow: riso(shadow),
  rotate,
  fill: {
    vector: {
      viewBox: 96,
      slice: 32,
      size: [72, 72],
      repeat: true,
      paths: [
        { d: LEAF_EDGE, color: bg },
        { d: VEINS_TL, strokeWidth: 1.6, color: vein },
        { d: VEINS_BR, strokeWidth: 1.6, color: vein },
      ],
    },
  },
})

const USER: ThemeMessageRule[] = [
  userLeaf('bg-user-message', 'text-user-message', '#1f8f4a', RISO_PINK, -1),
  userLeaf(INK_PURPLE, '#ffffff', '#c2307f', '#2fb35a', 0.8),
]

